import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = next();
        long best = Long.MAX_VALUE;
        // The final parities alternate starting from even (first=0) or odd (first=1).
        for (int first = 0; first < 2; first++) {
            long cost = 0;
            for (int i = 0; i < n; i++) {
                long v = a[i], target = first ^ (i & 1);
                while (v % 2 != target) {
                    v /= 2;
